// TH14 v1.00b st06.ecl::MainSub02 (593-629) + ECir00 (12-46) + ECir00_at (48-78).
// Card frame 0 is the MainSub02 entry; the shell buffer delays it by OPENING_BUFFER.
const TIME_LIMIT: int = 1824;
const OPENING_BUFFER: int = 120;

// Source etSprite(0,10,6): native type 10 keeps target slot 10 (TH14 wordlist).
const TH14_SHARD: int = 512;
const SHARD_COLOR: int = 6;

// Source 67-69: ANIM (birth stage omitted) -> WAIT 60 -> VELTIME 60 frames from the
// 3.0 spawn speed to scalar 0.5, angle kept (s=-999999).
xformdef SHARD_SLOW {
    wait(60);
    step_speed(0.5fx, 60 + 65536 * EASE_LINEAR);
}

// Source 48-78 ECir00_at. etNew and the whole config happen once (52-70); the loop
// at 524 only repeats etOn/wait(120), so every wave reuses one RANDRAD base angle.
async sub cir00_at() {
    wait(10);                                  // source 51
    var rank: int = global(GVAR_RANK);
    var shots: int = 1;                        // source 70 diffI(A,1,1,2,3)
    if rank == 2 { shots = 2; }
    if rank == 3 { shots = 3; }
    var ways: int = 60;                        // source 55-64 !N/!H/!LO all 60
    if rank == 0 { ways = 30; }                // source 55-56 !E 30
    var base: int = rand(65536);               // source 65 %RANDRAD, one draw per enemy
    sh_reset(0);                               // source 52 etNew(0)
    sh_sprite(0, TH14_SHARD, SHARD_COLOR);     // source 54 etSprite(0,10,6)
    sh_aim(0, 0);                              // source 53 etAim(0,3): fixed-direction ring
    sh_ring(0, 1);
    sh_count(0, ways, 1);                      // source 56-64 count, single layer
    sh_angle(0, base as angle, 0deg);          // source 65
    sh_speed(0, 3fx, 0fx);                     // source 66 etSpeed(3.0,0.2), M=1 uses first
    sh_dist(0, -12fx);                         // ANIM a=1 birth shift -4*initial speed (12px)
    sh_xform(0, SHARD_SLOW);                   // source 67-69 WAIT 60 + VELTIME
    for k in 0..shots {
        sh_fire(0);                            // source 73 etOn(0)
        wait(120);                             // source 74
    }
}

// Source 12-46 ECir00. f0/f1 = inherited F0/F1 move target, f2/i0 = inherited F2/I0.
async sub cir00(f0: fx, f1: fx, f2: fx, i0: int) {
    // Source 595-596 set I0=2 / F2=-pi/2 on the parent before each create; this
    // closure never reads them, so they are only kept as the inherited snapshot.
    // int slot 0 and fx slot 0 are owned by this card (no other writer).
    set_self_int(0, i0);
    set_self_fx(0, f2);
    set_invuln(65535);                         // training shell
    set_hurtbox(12fx);                         // source 18 setHurtbox(24,24): ordinary circle 24*0.5
    set_hitbox(8fx);                           // source 19 setHitbox(16,16): ordinary circle 16*0.5
    set_enemy_flag(ENEMY_NO_BODY, 1);          // source 23 flagSet(15): 0x2 body off in entrance
    // Source 30 movePosRel(160+RANDF2*32, RANDF2*64) is the immediate REL jump; it is
    // folded into the spawn point in create(). Source 31 interpolates REL to (F0,F1)
    // over 160 frames with mode 1 (t^2), relative to the (0,208) creation point.
    move_to(160, f0, 208fx + f1, EASE_QUAD_IN);
    wait(160);                                 // source 32
    set_enemy_flag(ENEMY_NO_BODY, 0);          // source 33 flagClear(15)
    spawn cir00_at();                          // source 36 @ECir00_at() async
    wait(400);                                 // source 37
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);   // source 38 moveVel(ANGLE_PLAYER, 0)
    move_speed(120, 0.5fx, EASE_LINEAR);       // source 39 moveSpeedTime(120, 0, 0.5)
    loop { wait(1000); }                       // source 41-44 wait(1000) loop
}

// Source 597-627: one enmCreate batch. Parent is the shell control enemy at (0,0),
// so enmCreate("ECir00",0,208) lands on world y=208.
sub create(f0: fx, f1: fx) {
    // Source 30: two independent RANDF2 reads in argument order (x first, then y).
    var ux: fx = (rand(65536)-32768) as fx / 32768;
    var jx: fx = 160fx + ux*32fx;
    var uy: fx = (rand(65536)-32768) as fx / 32768;
    var jy: fx = uy*64fx;
    // hp=320, score/item dropped by training policy (spawn_enemy arg order differs).
    _ = spawn_enemy(jx, 208fx + jy, 320, 0, 0, 0, cir00(f0, f1, -1.570796fx, 2));
}

async sub pattern() {
    wait(OPENING_BUFFER);                      // card [0,120) is shell buffer
    create(-160fx, -96fx);                     // source 597-599
    create(160fx, -96fx);                      // source 600-602
    wait(40);                                  // source 603
    create(-96fx, -160fx);                     // source 604-606
    create(96fx, -160fx);                      // source 607-609
    wait(40);                                  // source 610
    create(-32fx, -96fx);                      // source 611-613
    create(32fx, -96fx);                       // source 614-616
    wait(40);                                  // source 617
    create(0fx, -32fx);                        // source 618-620
    wait(40);                                  // source 621
    create(-160fx, -96fx);                     // source 622-624
    create(160fx, -96fx);                      // source 625-627
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
